package com.casystem.onboarding.controller;
import com.casystem.onboarding.model.*;import com.casystem.onboarding.repository.*;import com.casystem.onboarding.service.*;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class AdminControllerTest{
 @Mock UserRepository users;@Mock DocumentRepository docs;@Mock AuditLogRepository logs;@Mock TokenService tokens;@Mock CryptoService crypto;@Mock AuditService audit;@Mock MailSettingsRepository settings;@Mock MailService mail;@Mock PasswordEncoder encoder;@Mock HttpServletRequest req;AdminController c;User admin,user;Document doc;
 @BeforeEach void init(){MockitoAnnotations.openMocks(this);c=new AdminController(users,docs,logs,tokens,crypto,audit,settings,mail,encoder);admin=new User();admin.setId(1L);admin.setName("Admin");admin.setEmail("admin@test");admin.setRole("ADMIN");user=new User();user.setId(2L);user.setName("Ana");user.setEmail("ana@test");user.setRole("USER");user.setPhone("E:2291234567");user.setAddress("E:Calle 1");user.setPostalCode("E:91810");user.setSettlement("E:Centro");user.setMunicipality("E:Veracruz");user.setState("E:Veracruz");user.setDocumentNumber("E:ABC");doc=new Document();doc.setId(4L);doc.setUserId(2L);doc.setFileName("ine.pdf");doc.setContentType("application/pdf");doc.setEncryptedContent(new byte[]{8});when(tokens.userId(anyString())).thenReturn(1L);when(users.findById(1L)).thenReturn(Optional.of(admin));when(users.findById(2L)).thenReturn(Optional.of(user));when(req.getRemoteAddr()).thenReturn("ip");when(crypto.decrypt(anyString())).thenAnswer(i->{String s=i.getArgument(0);return s.startsWith("E:")?s.substring(2):s;});when(crypto.encrypt(anyString())).thenAnswer(i->"E:"+i.getArgument(0));when(crypto.decryptBytes(any())).thenReturn(new byte[]{1});when(docs.findByUserIdAndDeletedFalseOrderByCreatedAtDesc(2L)).thenReturn(List.of(doc));when(docs.findById(4L)).thenReturn(Optional.of(doc));when(users.findAll()).thenReturn(List.of(admin,user));when(encoder.encode(anyString())).thenReturn("hash");when(users.save(any())).thenAnswer(i->{User u=i.getArgument(0);if(u.getId()==null)u.setId(10L);return u;});}
 @Test void listaDetalleDocumentoYStats(){assertEquals(1,c.list("h",req).size());assertEquals("91810",c.one("h",2L,req).get("postalCode"));assertEquals(1,c.doc("h",4L,req).getBody().length);var s=c.stats("h",req);assertEquals(1,s.get("users"));assertEquals(1L,s.get("documents"));assertEquals(1L,s.get("completed"));}
 @Test void actividad(){AuditLog l=new AuditLog();l.setId(1L);l.setUserId(2L);l.setAction("LOGIN");l.setIp("ip");l.setCreatedAt(LocalDateTime.now());when(logs.findTop50ByOrderByCreatedAtDesc()).thenReturn(List.of(l));assertEquals(1,c.activity("h").size());}
 @Test void smtpGuardarProbarYLeer(){MailSettings s=new MailSettings();s.setId(1);s.setProvider("Gmail");s.setSenderEmail("a@test");s.setHost("smtp.gmail.com");s.setPort(587);s.setAuth(true);s.setStarttls(true);s.setEncryptedPassword("E:secret");when(settings.findById(1)).thenReturn(Optional.of(s));assertEquals(true,c.mailSettings("h").get("passwordConfigured"));assertEquals(true,c.saveMail("h",Map.of("provider","Gmail","senderEmail","a@test","host","smtp.gmail.com","port",587,"password","clave"),req).get("ok"));assertEquals(true,c.testMail("h",Map.of("senderEmail","a@test","host","smtp.gmail.com","port",587,"password","clave","testEmail","b@test"),req).get("ok"));verify(mail).test(any(),eq("b@test"));assertThrows(IllegalArgumentException.class,()->c.testMail("h",Map.of(),req));}
 @Test void administraAdministradores(){when(users.findByEmailAndDeletedFalse("nuevo@test")).thenReturn(Optional.empty());var r=c.createAdmin("h",Map.of("email","nuevo@test","name","Nuevo","password","Admin2026!"),req);assertEquals("nuevo@test",r.get("email"));assertEquals(1,c.admins("h").size());assertEquals(true,c.adminProfile("h",Map.of("name","Administrador General","newPassword","Nueva1234"),req).get("ok"));assertEquals("Administrador General",admin.getName());}
 @Test void rechazaNoAdmin(){user.setRole("USER");when(users.findById(1L)).thenReturn(Optional.of(user));assertThrows(SecurityException.class,()->c.admins("h"));}
}
